import React, { RefObject, useEffect, useState } from 'react';

import { HistogramExploreMode } from './HistogramExplore/HistogramExploreMode.js';
import { HistogramPanMode } from './HistogramPan/HistogramPanMode.js';
import { useHistogramMouseEventHandlers } from './hooks/useHistogramMouseEventHandlers.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { ChartOverlays } from '../../../core/components/overlays/ChartOverlays.js';
import { useZoomState } from '../../hooks/store/selectors.js';
import {
  useSetResetOverlaysState,
  useSetResetZoomState,
} from '../../hooks/store/state-setters.js';
import { useHistogramToolbar } from '../../hooks/useHistogramToolbar.js';
import { HistogramToolbar } from '../toolbar/HistogramToolbar.js';

export interface HistogramOverlaysProps {
  chartRef: RefObject<HTMLDivElement>;
}

export const HistogramOverlays = (props: HistogramOverlaysProps) => {
  const { chartRef } = props;
  const { leave: handleOverlayLeave, move: handleOverlayMove } =
    useHistogramMouseEventHandlers();
  const toolbar = useHistogramToolbar();
  const [showExploreMode, setShowExploreMode] = useState(true);
  const shouldShowToolbar = toolbar.enabled;
  const { width, height } = useGridPlotSize();
  const { zoomMode } = useZoomState();
  const setResetZoomstate = useSetResetZoomState();
  const setResetOverlaysState = useSetResetOverlaysState();

  const handleMouseEnter = () => {
    setResetOverlaysState();
    setShowExploreMode(false);
  };

  const handleMouseLeave = () => {
    setShowExploreMode(true);
  };

  useEffect(() => {
    setResetOverlaysState();
  }, [width, height]);

  const OverlayModeRender =
    zoomMode === 'explore' ? HistogramExploreMode : HistogramPanMode;

  const handleDoubleClick = () => {
    if (showExploreMode) {
      setResetZoomstate();
      setResetOverlaysState();
    }
  };

  return (
    <ChartOverlays
      onDoubleClick={handleDoubleClick}
      onMouseLeave={handleOverlayLeave}
      onMouseMove={handleOverlayMove}
      tooltipContainerRef={chartRef}
    >
      {showExploreMode && <OverlayModeRender />}
      {shouldShowToolbar && (
        <HistogramToolbar
          onMouseEnter={handleMouseEnter}
          onMouseLeave={handleMouseLeave}
        />
      )}
    </ChartOverlays>
  );
};
